"$vol = Get-Volume C
$freeGB = [math]::Round(($vol.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($vol.Size / 1GB), 2)
Write-Host "Current C Drive Free: $freeGB GB / Total: $totalGB GB"

$targets = @(
    @{ Name = "User Temp"; Path = "$env:TEMP" },
    @{ Name = "System Temp"; Path = "C:\Windows\Temp" },
    @{ Name = "Windows Update Download"; Path = "C:\Windows\SoftwareDistribution\Download" },
    @{ Name = "Recycle Bin"; Path = "C:\`$Recycle.Bin" },
    @{ Name = "User CrashDumps"; Path = "$env:LOCALAPPDATA\CrashDumps" },
    @{ Name = "Chrome Cache"; Path = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache" },
    @{ Name = "Chrome Code Cache"; Path = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache" },
    @{ Name = "Edge Cache"; Path = "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache" },
    @{ Name = "pip cache"; Path = "$env:LOCALAPPDATA\pip\cache" },
    @{ Name = "npm cache"; Path = "$env:LOCALAPPDATA\npm-cache" },
    @{ Name = "Cursor Cache"; Path = "$env:APPDATA\Cursor\Cache" },
    @{ Name = "VSCode Cache"; Path = "$env:APPDATA\Code\Cache" },
    @{ Name = "Antigravity Cache"; Path = "C:\Users\lg\.gemini\antigravity\brain" }
)

foreach ($t in $targets) {
    if (Test-Path $t.Path) {
        $files = Get-ChildItem -Path $t.Path -Recurse -File -ErrorAction SilentlyContinue
        if ($files) {
            $sum = ($files | Measure-Object -Property Length -Sum).Sum
            $gb = [math]::Round(($sum / 1GB), 2)
            Write-Host "$($t.Name) : $gb GB"
        } else {
            Write-Host "$($t.Name) : 0 GB"
        }
    } else {
        Write-Host "$($t.Name) : Not Found"
    }
}
"

"# Scan current status and big targets
$vol = Get-Volume C
$freeGB = [math]::Round(($vol.SizeRemaining / 1GB), 2)
$totalGB = [math]::Round(($vol.Size / 1GB), 2)
Write-Host "CURRENT_FREE_GB: $freeGB GB / $totalGB GB"

Write-Host "`n=== Large Directories in C:\Users\lg ==="
Get-ChildItem -Path "C:\Users\lg" -Force -ErrorAction SilentlyContinue | ForEach-Object {
    $item = $_
    if ($item.PSIsContainer) {
        $files = Get-ChildItem -Path $item.FullName -Recurse -File -Force -ErrorAction SilentlyContinue
        if ($files) {
            $sum = ($files | Measure-Object -Property Length -Sum).Sum
            $gb = [math]::Round(($sum / 1GB), 2)
            if ($gb -gt 0.3) {
                Write-Host "$($item.Name) : $gb GB"
            }
        }
    }
}

Write-Host "`n=== Checking Downloads Folder ==="
if (Test-Path "C:\Users\lg\Downloads") {
    Get-ChildItem -Path "C:\Users\lg\Downloads" -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Length -gt 50MB } | ForEach-Object {
        $fGB = [math]::Round(($_.Length / 1MB), 2)
        Write-Host "$($_.Name) : $fGB MB ($($_.FullName))"
    }
}
"

"Write-Host "=== .gemini Subdirectories ==="
Get-ChildItem -Path "C:\Users\lg\.gemini" -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
    $dir = $_
    $files = Get-ChildItem -Path $dir.FullName -Recurse -File -Force -ErrorAction SilentlyContinue
    if ($files) {
        $sum = ($files | Measure-Object -Property Length -Sum).Sum
        $gb = [math]::Round(($sum / 1GB), 2)
        Write-Host "$($dir.Name) : $gb GB"
    }
}

Write-Host "`n=== .gemini\antigravity\brain Subdirectories ==="
if (Test-Path "C:\Users\lg\.gemini\antigravity\brain") {
    $brains = Get-ChildItem -Path "C:\Users\lg\.gemini\antigravity\brain" -Directory -Force -ErrorAction SilentlyContinue
    Write-Host "Total Brain Sessions: $($brains.Count)"
    $oldBrains = $brains | Where-Object { $_.Name -ne "26e86a6c-7516-4656-86cf-d2a6ca54a02f" }
    $oldFiles = $oldBrains | Get-ChildItem -Recurse -File -Force -ErrorAction SilentlyContinue
    if ($oldFiles) {
        $oldSum = ($oldFiles | Measure-Object -Property Length -Sum).Sum
        Write-Host "Old Brain Sessions Size: $([math]::Round(($oldSum/1GB), 2)) GB"
    }
}
"
